INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 35, 'theory', 'Quiz: date and time');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 0, 'What does subtracting two dates, date(2025, 1, 1) - date(2024, 12, 25), give?', '["The number 7", "A timedelta object: 7 days", "A new date", "An error"]', 1, 'The difference of dates is a timedelta; it has .days and .total_seconds().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 1, 'Why does timedelta have no months or years?', '["They forgot to add them", "Their length is not constant: months have 28 to 31 days", "They are stored separately", "It is a Windows limitation"]', 1, 'That is why “plus a month” is computed by hand or with external libraries.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 2, 'Which format is best for storing a date in a file or database?', '["05.03.2024", "3/5/24", "2024-03-05 (ISO)", "March 5, 2024"]', 2, 'ISO notation is unambiguous and sorts as text in time order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 3, 'What happens when you compare a naive datetime with an aware one (with a time zone)?', '["The comparison works in UTC", "TypeError: can''t compare offset-naive and offset-aware", "None is returned", "Python adds a zone itself"]', 1, 'You can''t mix them: bring both to the same kind.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 4, 'How do you correctly measure how long code runs?', '["time.time() before and after", "time.perf_counter() before and after", "datetime.now() before and after", "sleep()"]', 1, 'perf_counter is the most precise timer and does not depend on system clock adjustments.');
